using System.Text;
using System.Text.Json;
using System.Security.Cryptography;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Runs;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private async Task RunTaskDuplicateActionAsync(CombatState live, Player player, bool last)
    {
        var enemy = live.Enemies.First(candidate => candidate.IsAlive);
        foreach (RelicModel relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        foreach (PowerModel power in live.Creatures.SelectMany(creature => creature.Powers).ToArray())
            await PowerCmd.Remove(power);
        await ClearPlayerPilesAsync(player);
        await SetBlockAsync(player.Creature, 0); await SetBlockAsync(enemy, 0);
        await CreatureCmd.SetMaxHp(enemy, Math.Max(256, enemy.MaxHp));
        await CreatureCmd.SetCurrentHp(enemy, 256); SetEnergy(player, 6);
        foreach (string id in new[] { "STRIKE_SILENT", "DEFEND_SILENT", "STRIKE_SILENT" })
            await InjectCardAsync(live, player, new() { CardId = id, Pile = "Hand" });
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
        CardModel[] actual = player.PlayerCombatState!.Hand.Cards.ToArray();
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        var parent = root.ForkSimulator();
        string State(CombatPredictionSimulator sim) => ContinuationStamp.CapturePredicted(player, sim,
            root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
        string Full(CombatPredictionSimulator sim) => State(sim) + "\nHISTORY=" + CardContinuationContractHistoryText(sim);
        string Hash(string text) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));
        var predictedHand = parent.State.GetPlayerCombatState(player).Hand.Cards;
        StateFingerprint firstKey = CombatBeamSolver.CaptureCardStateFingerprintForTesting(predictedHand[0]);
        StateFingerprint lastKey = CombatBeamSolver.CaptureCardStateFingerprintForTesting(predictedHand[2]);
        if (firstKey != lastKey) throw new InvalidOperationException("Ordinary duplicate cards have different local fingerprints.");
        string parentBefore = Full(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        var first = parent.Fork(); var second = parent.Fork();
        void Play(CombatPredictionSimulator sim, int index)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            var combat = (SimulatedCombatState)sim.State.CombatState;
            var card = sim.State.GetPlayerCombatState(player).Hand.Cards[index];
            if (!combat.CanPlayCard(sim, card)) throw new InvalidOperationException("Duplicate fixture card cannot play.");
            using (combat.BeginCardExecutionScope(new ForkableSet<uint>())) sim.ManualPlay(card, enemy, out _);
            CombatBeamSolver.SettleReplayActionBoundary(sim, combat); combat.AssertForkable();
        }
        Play(first, 0); Play(second, 2);
        string[] Hand(CombatPredictionSimulator sim) => sim.State.GetPlayerCombatState(player).Hand.Cards.Select(c => c.Preview.Id.Entry).ToArray();
        if (Hand(first).SequenceEqual(Hand(second)) || State(first) == State(second))
            throw new InvalidOperationException("Separated duplicates did not leave different ordered hands.");
        if (Full(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Duplicate action leaked into parent/live.");
        int index = last ? 2 : 0;
        var predicted = last ? second : first;
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(12));
        CardModel native = actual[index];
        GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
            queued => queued is PlayCardAction played && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), native),
            () => { if (!native.TryManualPlay(enemy)) throw new InvalidOperationException("Native duplicate card cannot play."); }, deadline.Token);
        await action.CompletionTask.WaitAsync(deadline.Token);
        if (State(predicted) != ContinuationStamp.CaptureLive(live).StateText)
            throw new InvalidOperationException("Native duplicate play differs in complete ordered state/RNG.");
        AssertSnapshotEqual(CaptureSimulated(predicted, (SimulatedCombatState)predicted.State.CombatState, player, enemy),
            CaptureActual(live, player, enemy), "DUPLICATE-ACTION", "play");
        string afterPlayHash = Hash(State(predicted));
        string[] actualHand = player.PlayerCombatState.Hand.Cards.Select(c => c.Id.Entry).ToArray();
        CombatRootSnapshot postPlayRoot = CombatRootSnapshot.Capture(live);
        var shuffleParent = postPlayRoot.ForkSimulator();
        string shuffleParentBefore = Full(shuffleParent), beforeShuffleLive = ContinuationStamp.CaptureLive(live).StateText;
        void MoveAndShuffle(CombatPredictionSimulator sim)
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            var cards = sim.State.GetPlayerCombatState(player).Hand.Cards.ToArray();
            foreach (var card in cards) sim.AddToPile(card, PileType.Discard);
            sim.Shuffle(player); ((SimulatedCombatState)sim.State.CombatState).AssertForkable();
        }
        var shuffled = shuffleParent.Fork(); MoveAndShuffle(shuffled);
        var opposite = (last ? first : second).Fork(); MoveAndShuffle(opposite);
        bool shuffleConvergedState = State(shuffled) == State(opposite);
        bool shuffleConvergedHistory = Full(shuffled) == Full(opposite);
        var children = Enumerable.Range(0, 16).Select(_ => shuffleParent.Fork()).ToArray();
        await Task.WhenAll(children.Select(child => Task.Run(() => MoveAndShuffle(child))));
        foreach (var child in children)
            if (Full(child) != Full(shuffled) || Full(child.Fork()) != Full(shuffled))
                throw new InvalidOperationException("Duplicate shuffle parallel/two-generation Fork differs.");
        if (Full(shuffleParent) != shuffleParentBefore || ContinuationStamp.CaptureLive(live).StateText != beforeShuffleLive)
            throw new InvalidOperationException("Duplicate shuffle leaked into parent/live.");
        foreach (var card in player.PlayerCombatState.Hand.Cards.ToArray())
        {
            var moved = await CardPileCmd.Add(card, PileType.Discard);
            if (!moved.success) throw new InvalidOperationException("Native duplicate discard move rejected.");
        }
        await CardPileCmd.Shuffle(new BlockingPlayerChoiceContext(), player);
        await RunManager.Instance.ActionExecutor.FinishedExecutingActions();
        if (State(shuffled) != ContinuationStamp.CaptureLive(live).StateText)
            throw new InvalidOperationException("Native duplicate shuffle differs in complete state/RNG.");
        AssertSnapshotEqual(CaptureSimulated(shuffled, (SimulatedCombatState)shuffled.State.CombatState, player, enemy),
            CaptureActual(live, player, enemy), "DUPLICATE-ACTION", "shuffle");
        _completedChecks.Add("DuplicateAction:SameLocalFingerprint:SeparatedInstances:DifferentOrderedHand:RealNativePlay:RealNativeShuffle:FullStateRng:SixteenParallelShuffleTwoGenerationFork:ParentLiveIsolation");
        _completedChecks.Add("TASK_DUPLICATE_ACTION " + JsonSerializer.Serialize(new { last,
            sameLocalFingerprint = firstKey == lastKey, actualHand, firstHand = Hand(first), secondHand = Hand(second),
            afterPlayHash, afterShuffleHash = Hash(State(shuffled)), shuffleConvergedState, shuffleConvergedHistory,
            draw = player.PlayerCombatState.DrawPile.Cards.Select(c => c.Id.Entry).ToArray(),
            forkCount = children.Length, parentUnchanged = Full(parent) == parentBefore,
            actualPrunes = 0, wholeRootCertified = false }));
    }
}

